sp_widget.css:
```css
.cfs-navbar {
  background: #ffffff;
  border-bottom: 1px solid #e5e7eb;

  min-height: 70px;

  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}


/* Container */

.cfs-navbar .container {
  min-height: 70px;

  display: flex;
  align-items: center;
  justify-content: space-between;
}


/* Brand */

.navbar-brand {
  margin: 0;
  padding: 0;
}

.navbar-brand a {
  display: flex;
  align-items: center;

  gap: 10px;

  text-decoration: none;

  color: #1f2937;
}

.brand-icon {
  width: 40px;
  height: 40px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 8px;

  background: #0f766e;

  color: #ffffff;

  font-size: 18px;
}

.brand-name {
  font-size: 17px;
  font-weight: 600;
}


/* Navigation */

.cfs-navbar .navbar-nav {
  margin: 0;

  display: flex;
  align-items: center;

  gap: 8px;
}

.cfs-navbar .navbar-nav > li > a {
  color: #4b5563;

  font-size: 14px;
  font-weight: 500;

  padding: 10px 14px;

  border-radius: 6px;

  text-decoration: none;
}


/* Hover */

.cfs-navbar .navbar-nav > li > a:hover {
  background: #f0fdfa;

  color: #0f766e;
}


/* Login button */

.cfs-navbar .login-btn {
  background: #0f766e !important;

  color: #ffffff !important;

  margin-left: 8px;

  padding: 10px 20px !important;

  border-radius: 7px !important;

  font-weight: 600 !important;
}

.cfs-navbar .login-btn:hover {
  background: #115e59 !important;

  color: #ffffff !important;
}


/* Mobile */

@media (max-width: 767px) {

  .cfs-navbar .container {
    flex-direction: column;

    padding: 12px 15px;
  }

  .cfs-navbar .navbar-nav {
    width: 100%;

    justify-content: center;

    margin-top: 10px;

    flex-wrap: wrap;
  }

  .cfs-navbar .navbar-nav > li > a {
    padding: 8px 10px;
  }

}
```

sp_widget.script:
(function() {

    data.loggedIn = gs.isLoggedIn();

    data.userName = '';
    data.userInitial = '';

    if (data.loggedIn) {

        var user = gs.getUser();

        data.userName = user.getDisplayName();

        if (data.userName) {
            data.userInitial =
                data.userName.substring(0, 1).toUpperCase();
        }
    }


    /*
     * NAVIGATION CONFIGURATION
     *
     * Change these values according
     * to your actual portal page IDs.
     */

    data.menuItems = [

        {
            label: 'Home',
            icon: 'fa fa-home',
            url: '?id=food_home',
            visible: true
        },

        {
            label: 'Services',
            icon: 'fa fa-th-large',
            url: '?id=food_services',
            visible: true
        },

        {
            label: 'My Complaints',
            icon: 'fa fa-list-alt',
            url: '?id=my_complaints',
            visible: data.loggedIn
        },

        {
            label: 'Feedback',
            icon: 'fa fa-comment',
            url: '?id=food_feedback',
            visible: data.loggedIn
        }

    ];

})();
